		/* If the current node is closer than the previous closest one */
		if (current_distance < min_distance)
		{
			/* Check if this node is on a non-footway road */
			if (graph.get_node_to_roadmap().find(node.index_) != graph.get_node_to_roadmap().end())
			{
				min_distance = current_distance;
				closest_node = &node;
			}
		}
	}

	return closest_node;

